                        .on_hover(popup_hover)
                        .on_dismiss(dismiss)
                        .child(
                            entry.viewport_part(div()).child(
                                entry
                                    .content_part(div().flex_col().gap(6.0))
                                    .child(self.control("Overview"))
                                    .child(menu.link_part(
                                        "pricing",
                                        false,
                                        text("Pricing").text_sm().text_color(palette.accent),
                                    )),
                            ),
                        ),
                ),
            );
        }
    }
    self.section(
        "Navigation menu",
        div()
            .relative()
            .child(menu.root_part(div()).child(list))
            .child(panels),
    )
}

number-field.code:
fn number_field(&self, cx: &mut ViewContext<'_, Self>, colors: Palette) -> Element {
    let field = NumberField::new("quantity");
    let edit = cx.input_listener(field.input_id(), |view: &mut Self, value, cx| {
        if view.quantity.set_text(value) {
            cx.invalidate();
        }
    });
    // The input is marked invalid while its text is out of range, and QuickGUI blocks Return
    // submission for an invalid control, so commit from an ordinary key listener.
    let commit = cx.key_down_listener(field.input_id(), |view: &mut Self, event, cx| {
        if event.key == Key::Enter && view.quantity.commit() {
            cx.invalidate();
        }
    });
    let press_up =
        cx.mouse_down_listener(field.increment_id(), |view: &mut Self, _event, cx| {
            view.quantity.press_step(true, Instant::now());
            cx.invalidate();
        });
    let press_down =
        cx.mouse_down_listener(field.decrement_id(), |view: &mut Self, _event, cx| {
            view.quantity.press_step(false, Instant::now());
            cx.invalidate();
        });
    let release = cx.mouse_up_listener("quantity", |view: &mut Self, _event, cx| {
        if view.quantity.release_step() {
            view.repeat = None;
            cx.invalidate();
        }
    });
    // Base UI's ScrubArea: a captured drag over the handle changes the value without touching
    // the caret. Shift scrubs by the large step and Alt by the small one.
    let scrub = cx.pointer_listener(field.scrub_area_id(), |view: &mut Self, event, cx| {
        if view.quantity.apply_scrub(event) {
            cx.invalidate();
        }
    });

    let stepper = |glyph: &'static str| {
        div()
            .size(22.0, 20.0)
            .flex_row()
            .items_center()
            .justify_center()
            .rounded(6.0)
            .border(1.0, colors.border)
            .bg(colors.track)
            .child(text(glyph).text_sm())
    };

    field
        .root_part(
            div()
                .flex_row()
                .items_center()
                .gap_2()
                .on_mouse_up(MouseButton::Left, release)
                .child(
                    field.input_part(
                        &self.quantity,
                        text_input(self.quantity.text().clone())
                            .w(96.0)
                            .px_2()
                            .py_1()
                            .rounded_md()
                            .border(1.0, colors.border)
                            .bg(colors.track)
                            .text_color(colors.foreground)
                            .invalid_style(|state| state.border(1.0, colors.warning))
                            .on_input(edit)
                            .on_key_down(commit),
                    ),
                )
                .child(field.decrement_part(
                    &self.quantity,
                    stepper("−").on_mouse_down(MouseButton::Left, press_down),
                ))
                .child(field.increment_part(
                    &self.quantity,
                    stepper("+").on_mouse_down(MouseButton::Left, press_up),
                )),
        )
        .child(
            field
                .scrub_area_part(
                    &self.quantity,
                    div()
                        .relative()
                        .size(28.0, 20.0)
                        .flex_row()
                        .items_center()
                        .justify_center()
                        .rounded(6.0)
                        .border(1.0, colors.border)
                        .bg(if self.quantity.is_scrubbing() {
                            colors.accent
                        } else {
                            colors.track
                        })
                        .on_pointer(scrub),
                )
                .child(text("↔").text_sm())
                .children(self.quantity.is_scrubbing().then(|| {
                    field.scrub_area_cursor_part(
                        div()
                            .absolute()
                            .top(-14.0)
                            .left(6.0)
                            .size(6.0, 6.0)
                            .rounded(3.0)
                            .bg(colors.foreground),
                    )
                })),
        )
}

