        .rounded_md()
        .border(1.0, colors.border)
        .bg(if pressed {
            colors.pressed
        } else {
            colors.surface
        })
        .hover(|state| state.border(1.0, colors.muted))
        .focus(|state| state.border(2.0, colors.accent))
