fn render(&mut self, cx: &mut ViewContext<'_, Self>) -> impl IntoElement {
    let palette = BarPalette::new(cx.appearance().is_dark());

    let command = cx.action_listener(
        "menubar-gallery",
        |view: &mut Self, action: &Command, cx| {
            view.status = Arc::from(match action {
                Command::New => "New Window",
                Command::Open => "Open…",
                Command::Undo => "Undo",
                Command::Redo => "Redo",
                Command::ToggleSidebar(_) => "Toggled the sidebar",
                Command::Zoom => "Actual Size",
            });
            if let Command::ToggleSidebar(next) = action {
                view.sidebar = *next;
            }
            view.menubar.close();
            cx.invalidate();
        },
    );

    let bar = Menubar::new("menubar");
    let mut bar_row = bar
        .root_part(self.menubar, div())
        .accessibility_label("Application menus")
        .flex_row()
        .items_center()
        .gap_1()
        .h(30.0)
        .px(8.0)
        .bg(palette.bar)
        .border(1.0, palette.border);
    for index in 0..self.menubar.menu_count() {
        let item = bar.item(self.menubar, index).expect("a declared menu");
        let open = item.is_open();
        let element = item.item_part(
            div()
                .px(10.0)
                .h(24.0)
                .flex_row()
                .items_center()
                .rounded(5.0)
                .bg(if open {
                    palette.open
                } else {
                    Color::TRANSPARENT
                })
                .hover(move |hover| hover.bg(palette.open))
                .child(text(MENU_TITLES[index]).text_sm()),
        );
        bar_row = bar_row.child(item.key_part(cx, element, Self::menubar));
    }

    let surface = self.menubar.open_menu().map(|index| {
        let root = div()
            .absolute()
            .top(30.0)
            .left(8.0 + index as f32 * 78.0)
            .w(220.0)
            .flex_col()
            .p(4.0)
            .rounded(8.0)
            .border(1.0, palette.border)
            .bg(palette.surface)
            .shadow_lg();
        let render_item =
            move |item: &PopoverMenuItem, state: PopoverMenuItemState| -> Element {
                if item.kind() == PopoverMenuItemKind::Separator {
                    return div().h(1.0).my(4.0).bg(palette.border);
                }
                div()
                    .h(26.0)
                    .px(8.0)
                    .flex_row()
                    .items_center()
                    .justify_between()
                    .rounded(5.0)
                    .bg(if state.highlighted {
                        palette.highlight
                    } else {
                        Color::TRANSPARENT
                    })
                    .child(text(item.label().clone()).text_sm())
                    .child(
                        text(
                            item.shortcut_text()
                                .cloned()
                                .unwrap_or_else(|| Arc::from("")),
                        )
                        .text_xs()
                        .text_color(palette.muted),
                    )
            };
        let dismiss = |view: &mut Self, cx: &mut quickgui::EventContext| {
            view.menubar.close();
            cx.invalidate();
        };
        match index {
            0 => self.file.element(
                cx,
                "file-menu",
                |view| &mut view.file,
                root,
                render_item,
                dismiss,
            ),
            1 => self.edit.element(
                cx,
                "edit-menu",
                |view| &mut view.edit,
                root,
                render_item,
                dismiss,
            ),
            _ => self.view.element(
                cx,
                "view-menu",
                |view| &mut view.view,
                root,
                render_item,
                dismiss,
            ),
        }
    });

    let mut page = div()
        .id("menubar-gallery")
        .on_action(command)
        .size_full()
        .relative()
        .flex_col()
        .bg(palette.page)
        .text_color(palette.foreground)
        .child(bar_row)
        .child(
            div()
                .flex_1()
                .min_h(0.0)
                .flex_col()
                .gap_2()
                .p(20.0)
                .child(text("In-window menubar").text_lg().font_semibold())
                .child(
                    text("The bar owns one Tab stop. Arrows move between menus and keep switching while one is open, hovering another title switches menus, and Escape closes without leaving the bar.")
                        .wrap()
                        .text_sm()
                        .text_color(palette.muted),
                )
                .child(
                    text(format!(
                        "Sidebar is {}",
                        if self.sidebar { "visible" } else { "hidden" }
                    ))
                    .text_sm(),
                )
                .child(text(self.status.clone()).text_xs().text_color(palette.muted)),
        );
    if let Some(surface) = surface {
        page = page.child(surface);
    }
    page
}

